/*
 * High-performance portfolio calculations using C extension
 *
 * Uses the NumPy C API for zero-copy access to C-contiguous double arrays.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *cov_array;
    PyArrayObject *weights = NULL, *cov = NULL;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array))
        return NULL;

    /* Convert to C-contiguous double arrays (zero-copy when already suitable). */
    weights = (PyArrayObject *)PyArray_FROM_OTF((PyObject *)weights_array,
                                                NPY_DOUBLE,
                                                NPY_ARRAY_IN_ARRAY);
    if (weights == NULL)
        return NULL;

    cov = (PyArrayObject *)PyArray_FROM_OTF((PyObject *)cov_array,
                                            NPY_DOUBLE,
                                            NPY_ARRAY_IN_ARRAY);
    if (cov == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    if (PyArray_NDIM(weights) != 1 || PyArray_NDIM(cov) != 2) {
        PyErr_SetString(PyExc_ValueError,
                        "weights must be 1D and cov_matrix must be 2D");
        Py_DECREF(weights);
        Py_DECREF(cov);
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights, 0);
    npy_intp rows = PyArray_DIM(cov, 0);
    npy_intp cols = PyArray_DIM(cov, 1);

    if (rows != n || cols != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix dimensions must match the number of weights");
        Py_DECREF(weights);
        Py_DECREF(cov);
        return NULL;
    }

    const double *x = (const double *)PyArray_DATA(weights);
    const double *S = (const double *)PyArray_DATA(cov);

    /* risk = sqrt(x^T S x), accumulating in the same order as the baseline. */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *row = S + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            row_sum += row[j] * x[j];
        }
        risk_squared += x[i] * row_sum;
    }

    Py_DECREF(weights);
    Py_DECREF(cov);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *returns_array;
    PyArrayObject *weights = NULL, *returns = NULL;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array))
        return NULL;

    weights = (PyArrayObject *)PyArray_FROM_OTF((PyObject *)weights_array,
                                                NPY_DOUBLE,
                                                NPY_ARRAY_IN_ARRAY);
    if (weights == NULL)
        return NULL;

    returns = (PyArrayObject *)PyArray_FROM_OTF((PyObject *)returns_array,
                                                NPY_DOUBLE,
                                                NPY_ARRAY_IN_ARRAY);
    if (returns == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    if (PyArray_NDIM(weights) != 1 || PyArray_NDIM(returns) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must be 1D");
        Py_DECREF(weights);
        Py_DECREF(returns);
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(returns, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have the same length");
        Py_DECREF(weights);
        Py_DECREF(returns);
        return NULL;
    }

    const double *x = (const double *)PyArray_DATA(weights);
    const double *r = (const double *)PyArray_DATA(returns);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        total_return += x[i] * r[i];
    }

    Py_DECREF(weights);
    Py_DECREF(returns);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}
