/*
 * High-performance portfolio calculations using C extension
 *
 * NumPy arrays are accessed through the NumPy C API (zero-copy when they are
 * already C-contiguous doubles).  Plain Python sequences are consumed directly
 * so that large nested covariance lists do not need to be materialised as a
 * NumPy array first.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Obtain a C-contiguous double vector from a NumPy array or Python sequence. */
static int get_double_vector(PyObject *obj, PyArrayObject **arr,
                             double **buf, const double **data,
                             npy_intp *n) {
    *arr = NULL;
    *buf = NULL;

    if (PyArray_Check(obj)) {
        PyArrayObject *a = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (a == NULL)
            return -1;
        if (PyArray_NDIM(a) != 1) {
            PyErr_SetString(PyExc_ValueError, "expected a 1D array");
            Py_DECREF(a);
            return -1;
        }
        *arr = a;
        *n = PyArray_DIM(a, 0);
        *data = (const double *)PyArray_DATA(a);
        return 0;
    }

    PyObject *seq = PySequence_Fast(obj, "expected a sequence of numbers");
    if (seq == NULL)
        return -1;

    Py_ssize_t len = PySequence_Fast_GET_SIZE(seq);
    double *values = (double *)malloc(sizeof(double) * (len > 0 ? len : 1));
    if (values == NULL) {
        Py_DECREF(seq);
        PyErr_NoMemory();
        return -1;
    }

    PyObject **items = PySequence_Fast_ITEMS(seq);
    for (Py_ssize_t i = 0; i < len; ++i) {
        double value = PyFloat_AsDouble(items[i]);
        if (value == -1.0 && PyErr_Occurred()) {
            free(values);
            Py_DECREF(seq);
            return -1;
        }
        values[i] = value;
    }
    Py_DECREF(seq);

    *buf = values;
    *n = (npy_intp)len;
    *data = values;
    return 0;
}

static void release_double_vector(PyArrayObject *arr, double *buf) {
    Py_XDECREF(arr);
    free(buf);
}

/* Compute sqrt(x^T S x) for a C-contiguous n-by-n matrix. */
static double risk_from_buffer(const double *x, const double *S, npy_intp n) {
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *row = S + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            row_sum += row[j] * x[j];
        }
        risk_squared += x[i] * row_sum;
    }
    return sqrt(risk_squared);
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;
    PyArrayObject *weights_arr = NULL, *cov_arr = NULL;
    double *weights_buf = NULL, *cov_buf = NULL;
    const double *x = NULL, *S = NULL;
    npy_intp n = 0;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    if (get_double_vector(weights_obj, &weights_arr, &weights_buf,
                          &x, &n) != 0)
        return NULL;

    /* Fast path for NumPy covariance matrices. */
    if (PyArray_Check(cov_obj)) {
        cov_arr = (PyArrayObject *)PyArray_FROM_OTF(
            cov_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (cov_arr == NULL)
            goto error;
        if (PyArray_NDIM(cov_arr) != 2 ||
            PyArray_DIM(cov_arr, 0) != n ||
            PyArray_DIM(cov_arr, 1) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix dimensions must match the number of weights");
            goto error;
        }
        S = (const double *)PyArray_DATA(cov_arr);
        double result = risk_from_buffer(x, S, n);
        release_double_vector(weights_arr, weights_buf);
        Py_DECREF(cov_arr);
        return PyFloat_FromDouble(result);
    }

    /* Fast path for nested Python sequences: read rows without flattening. */
    PyObject *cov_seq = PySequence_Fast(cov_obj,
                                        "cov_matrix must be a 2D sequence");
    if (cov_seq == NULL)
        goto error;

    Py_ssize_t rows = PySequence_Fast_GET_SIZE(cov_seq);
    if ((npy_intp)rows != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix dimensions must match the number of weights");
        Py_DECREF(cov_seq);
        goto error;
    }

    PyObject **row_items = PySequence_Fast_ITEMS(cov_seq);
    double risk_squared = 0.0;

    for (npy_intp i = 0; i < n; ++i) {
        PyObject *row_obj = row_items[i];
        PyObject *row_seq;
        int row_owned = 0;

        if (PyList_Check(row_obj) || PyTuple_Check(row_obj)) {
            row_seq = row_obj;
        } else {
            row_seq = PySequence_Fast(row_obj, "each covariance row must be a sequence");
            if (row_seq == NULL) {
                Py_DECREF(cov_seq);
                goto error;
            }
            row_owned = 1;
        }

        Py_ssize_t cols;
        PyObject **items;
        if (PyList_Check(row_seq)) {
            cols = PyList_GET_SIZE(row_seq);
            items = ((PyListObject *)row_seq)->ob_item;
        } else if (PyTuple_Check(row_seq)) {
            cols = PyTuple_GET_SIZE(row_seq);
            items = ((PyTupleObject *)row_seq)->ob_item;
        } else {
            cols = PySequence_Fast_GET_SIZE(row_seq);
            items = PySequence_Fast_ITEMS(row_seq);
        }

        if ((npy_intp)cols != n) {
            PyErr_SetString(PyExc_ValueError,
                            "each covariance row must match the number of weights");
            if (row_owned)
                Py_DECREF(row_seq);
            Py_DECREF(cov_seq);
            goto error;
        }

        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            double value = PyFloat_AsDouble(items[j]);
            if (value == -1.0 && PyErr_Occurred()) {
                if (row_owned)
                    Py_DECREF(row_seq);
                Py_DECREF(cov_seq);
                goto error;
            }
            row_sum += value * x[j];
        }
        risk_squared += x[i] * row_sum;

        if (row_owned)
            Py_DECREF(row_seq);
    }

    Py_DECREF(cov_seq);
    release_double_vector(weights_arr, weights_buf);
    return PyFloat_FromDouble(sqrt(risk_squared));

error:
    release_double_vector(weights_arr, weights_buf);
    Py_XDECREF(cov_arr);
    return NULL;
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;
    PyArrayObject *weights_arr = NULL, *returns_arr = NULL;
    double *weights_buf = NULL, *returns_buf = NULL;
    const double *x = NULL, *r = NULL;
    npy_intp n = 0, m = 0;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    if (get_double_vector(weights_obj, &weights_arr, &weights_buf,
                          &x, &n) != 0)
        return NULL;

    if (get_double_vector(returns_obj, &returns_arr, &returns_buf,
                          &r, &m) != 0) {
        release_double_vector(weights_arr, weights_buf);
        return NULL;
    }

    if (m != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have the same length");
        release_double_vector(weights_arr, weights_buf);
        release_double_vector(returns_arr, returns_buf);
        return NULL;
    }

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        total_return += x[i] * r[i];
    }

    release_double_vector(weights_arr, weights_buf);
    release_double_vector(returns_arr, returns_buf);
    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}
